{"content":"#!/usr/bin/awk -f
# -*- coding: utf-8 -*-
# 独立的第二套实现（awk），用于与 artifacts/verify.py 交叉核验总计。
# 用法: awk -f artifacts/verify_awk.awk uploads/sales.csv > artifacts/.verify_awk.csv
#
# 与 Python 版刻意采用不同的聚合路径:
#   Python: 先按 channel 分组求和, 再相加得到月合计
#   awk   : 单遍扫描直接累加到 10 个累加器桶, 不做任何分组后合并
# 若两套实现结果不一致, 说明任一方的聚合逻辑有误。

BEGIN {
    FS = ",";
    months[1] = "2026-08"; months[2] = "2026-09"; months[3] = "2026-10";
    chans[1] = "官网";   chans[2] = "渠道";
    mi = 1; ci = 1;
}

NR == 1 {
    # 校验表头顺序
    expected = "month,channel,revenue,orders,refunds,cost";
    if ($0 != expected) {
        printf("ERROR: 表头不符合预期\n期望: %s\n实际: %s\n", expected, $0) > "/dev/stderr";
        exit 1;
    }
    next;
}

{
    m = $1; ch = $2;
    if (m !~ /^2026-(08|09|10)$/) {
        printf("ERROR: 非法月份 %s\n", m) > "/dev/stderr"; exit 1;
    }
    if (ch != "官网" && ch != "渠道") {
        printf("ERROR: 非法渠道 %s\n", ch) > "/dev/stderr"; exit 1;
    }
    for (i = 3; i <= 6; i++) {
        if ($i !~ /^[0-9]+(\.[0-9]+)?$/) {
            printf("ERROR: 第 %d 行第 %d 列不是数字: %s\n", NR, i, $i) > "/dev/stderr"; exit 1;
        }
    }

    rev = $3 + 0; ord = $4 + 0; ref = $5 + 0; cst = $6 + 0;
    if (ord <= 0) { printf("ERROR: 第 %d 行 orders <= 0\n", NR) > "/dev/stderr"; exit 1; }

    # --- 单遍累加: 月合计桶 ---
    mrev[m] += rev; mord[m] += ord; mref[m] += ref; mcst[m] += cst;
    # --- 单遍累加: 月×渠道桶 ---
    k = m "|" ch;
    crev[k] += rev; cord[k] += ord; cref[k] += ref; ccst[k] += cst;
    # --- 单遍累加: 全量总计桶 ---
    trev += rev; tord += ord; tref += ref; tcst += cst;
    nrows++;
}

END {
    if (nrows != 6) {
        printf("ERROR: 数据行数应为 6, 实际 %d\n", nrows) > "/dev/stderr"; exit 1;
    }
    printf("month,scope,revenue,orders,refunds,cost,aov,refund_rate,gross_profit,gross_margin\n");

    for (i = 1; i <= 3; i++) {
        m = months[i];
        emit(m, "总计", mrev[m], mord[m], mref[m], mcst[m]);
        for (j = 1; j <= 2; j++) {
            ch = chans[j];
            k = m "|" ch;
            emit(m, ch, crev[k], cord[k], cref[k], ccst[k]);
        }
    }
    emit("2026-08~2026-10", "总计", trev, tord, tref, tcst);
}

function emit(m, scope, rev, ord, ref, cst,   aov, rr, gp, gm) {
    aov = (ord > 0) ? rev / ord : 0;
    rr  = (rev > 0) ? ref / rev : 0;
    gp  = rev - cst;
    gm  = (rev > 0) ? gp / rev : 0;
    printf "%s,%s,%.10f,%.10f,%.10f,%.10f,%.10f,%.10f,%.10f,%.10f\n",
        m, scope, rev, ord, ref, cst, aov, rr, gp, gm;
}
